// Generated by the module (addServerTemplate); declared here for the package's own build.
declare module '#atelier-schema' {
  export const collections: Record<string, import('./types').CollectionDefinition>
  export const singletons: Record<string, import('./types').SingletonDefinition>
  export const roles: import('../shared/policy').Roles
  export const tables: Record<string, import('./db/tables').TableSpec>
  export const blocks: Record<string, import('../shared/blocks').BlockSchema>
  export const patterns: Record<string, import('./types').PatternDefinition>
}

// The app's migrations, bundled at build time by dialect
declare module '#atelier-migrations' {
  export const migrations: Partial<Record<import('./db/driver').Dialect, { name: string, sql: string }[]>>
}

// The database drivers the app installed, chosen at build time
declare module '#atelier-drivers' {
  export const drivers: import('./db/driver').DriverLoaders
}

// nodemailer, when the app installed it (SMTP email)
declare module '#atelier-mailer' {
  export const nodemailer: (() => Promise<{ createTransport: (url: string) => { sendMail: (message: Record<string, unknown>) => Promise<unknown> } }>) | undefined
}
